import streamlit as st
import pandas as pd
import gzip
import base64
import json

st.set_page_config(
    page_title="Smart City Traffic Congestion Prediction",
    page_icon="🚦",
    layout="wide"
)

DATA_FILE = "traffic_data_realistic_2024_2026_3456.csv"

# Encoder mappings are embedded so the app does NOT need sklearn/joblib
ENCODER_CLASSES = {"Location":["Airport","Downtown","East","Industrial","North","South","West"],"Vehicle Type":["Bike","Bus","Car","Truck"],"Weather":["Cloudy","Foggy","Rainy","Sunny"],"Holiday":["No","Yes"],"Accident":["No","Yes"],"Congestion Level":["High","Low","Medium"]}

# The trained Random Forest is exported as plain tree data and embedded here.
# This allows the app to make the same tree-based predictions without importing sklearn.
FOREST_B64 = """"""

FEATURES = [
    "Location", "Traffic Volume", "Vehicle Type", "Weather",
    "Temperature", "Holiday", "Speed", "Accident",
    "Year", "Month", "Day", "DayOfWeek", "WeekOfYear", "Hour"
]

@st.cache_resource
def load_forest():
    raw = gzip.decompress(base64.b64decode(FOREST_B64))
    return json.loads(raw.decode())

@st.cache_data
def load_data():
    data = pd.read_csv(DATA_FILE)
    data["Date"] = pd.to_datetime(data["Date"], errors="coerce")
    return data

def encode_value(column, value):
    classes = ENCODER_CLASSES[column]
    if value not in classes:
        raise ValueError(f"Unknown value '{value}' for {column}.")
    return classes.index(value)

def tree_predict_proba(tree, x):
    node = 0
    left = tree["l"]
    right = tree["r"]
    feature = tree["f"]
    threshold = tree["th"]

    while left[node] != right[node]:
        f = feature[node]
        if x[f] <= threshold[node]:
            node = left[node]
        else:
            node = right[node]

    counts = tree["v"][node]
    total = sum(counts)
    if total <= 0:
        return [1.0 / len(counts)] * len(counts)
    return [c / total for c in counts]

def forest_predict(x):
    forest = load_forest()
    probs = [0.0, 0.0, 0.0]
    for tree in forest:
        p = tree_predict_proba(tree, x)
        for i in range(len(probs)):
            probs[i] += p[i]
    n = len(forest)
    probs = [p / n for p in probs]
    best = max(range(len(probs)), key=lambda i: probs[i])
    label = ENCODER_CLASSES["Congestion Level"][best]
    return label, probs[best] * 100

try:
    df = load_data()
except Exception as e:
    st.error("Unable to load the dataset file.")
    st.info(
        "Make sure traffic_data_realistic_2024_2026_3456.csv "
        "is in the same GitHub folder as app_combined.py."
    )
    st.exception(e)
    st.stop()

st.sidebar.title("🚦 Smart City Traffic")
page = st.sidebar.radio("Navigation", ["Dashboard", "Future Prediction"])

if page == "Dashboard":
    st.title("📊 Smart City Traffic Congestion Dashboard")
    st.caption("Traffic congestion analysis and future prediction")

    c1, c2, c3, c4 = st.columns(4)
    c1.metric("Total Records", f"{len(df):,}")
    c2.metric("Average Speed", f"{df['Speed'].mean():.1f} km/h")
    c3.metric("Average Traffic", f"{df['Traffic Volume'].mean():.0f}")

    accidents = (
        (df["Accident"].astype(str).str.strip().str.lower() == "yes").sum()
        if "Accident" in df.columns else 0
    )
    c4.metric("Accidents", f"{int(accidents):,}")

    st.subheader("Traffic Volume Trend")
    trend = df.groupby("Date")["Traffic Volume"].mean()
    st.line_chart(trend)

    col1, col2 = st.columns(2)

    with col1:
        st.subheader("Average Traffic by Vehicle Type")
        vehicle = (
            df.groupby("Vehicle Type")["Traffic Volume"]
            .mean()
            .sort_values(ascending=False)
        )
        st.bar_chart(vehicle)

    with col2:
        st.subheader("Congestion Distribution")
        st.bar_chart(df["Congestion Level"].value_counts())

    st.subheader("Average Traffic by Weather")
    weather = (
        df.groupby("Weather")["Traffic Volume"]
        .mean()
        .sort_values(ascending=False)
    )
    st.bar_chart(weather)

    st.subheader("Data Preview")
    st.dataframe(df.head(20), use_container_width=True)

else:
    st.title("🔮 Future Congestion Prediction")
    st.write("Enter the expected traffic conditions to predict congestion.")

    from datetime import date, time
    d = st.date_input("Future Date", value=date.today())
    t = st.time_input("Time", value=time(8, 0))

    location = st.selectbox("Location", ENCODER_CLASSES["Location"])
    traffic = st.number_input(
        "Traffic Volume", min_value=0, max_value=5000, value=500, step=10
    )
    vehicle = st.selectbox("Vehicle Type", ENCODER_CLASSES["Vehicle Type"])
    weather = st.selectbox("Weather", ENCODER_CLASSES["Weather"])
    temp = st.number_input(
        "Temperature", min_value=-10.0, max_value=60.0, value=30.0, step=0.5
    )
    holiday = st.selectbox("Holiday", ENCODER_CLASSES["Holiday"])
    speed = st.number_input(
        "Speed", min_value=0.0, max_value=150.0, value=40.0, step=1.0
    )
    accident = st.selectbox("Accident", ENCODER_CLASSES["Accident"])

    if st.button("🚦 Predict Congestion", type="primary"):
        try:
            x = [
                encode_value("Location", location),
                float(traffic),
                encode_value("Vehicle Type", vehicle),
                encode_value("Weather", weather),
                float(temp),
                encode_value("Holiday", holiday),
                float(speed),
                encode_value("Accident", accident),
                int(d.year),
                int(d.month),
                int(d.day),
                int(d.weekday()),
                int(d.isocalendar().week),
                int(t.hour)
            ]

            label, confidence = forest_predict(x)

            st.success(f"Predicted Congestion: {label}")
            st.metric("Prediction Confidence", f"{confidence:.2f}%")

        except Exception as e:
            st.error("Prediction failed.")
            st.exception(e)
